const cfg = $('Config - Spreadsheet IDs').first().json;

const rowsFrom = (name) => $(name).all().map(x => x.json || {}).filter(x => Object.keys(x).length > 0);
const orders = rowsFrom('Read Orders A:Q');
const history = rowsFrom('Read History E:G');
const costMain = rowsFrom('Read Cost - Account Mileage');
const costFuel = rowsFrom('Read Cost - Fuel F');
const costBaseLabor = rowsFrom('Read Cost - Base Labor G:H');
const costPickupTrip = rowsFrom('Read Cost - Pickup Trip I:J');
const costSixTrip = rowsFrom('Read Cost - 6W Trip K:L');
const costTrailerTrip = rowsFrom('Read Cost - Trailer Trip M:N');
const costToll = rowsFrom('Read Cost - Toll O:Q');
const carRows = rowsFrom('Read CAR_DATA A:C');

const CANON = {
  PICKUP: 'รถกระบะ 4 ล้อ',
  SIX: 'รถบรรทุก 6 ล้อ',
  TRAILER: 'รถบรรทุกพ่วง (6ล้อ+6ล้อ)',
};
const TYPE_RANK = { PICKUP: 1, SIX: 2, TRAILER: 3 };
const SPEED = {
  PICKUP: Number(cfg.SPEED_PICKUP_KMH),
  SIX: Number(cfg.SPEED_6W_KMH),
  TRAILER: Number(cfg.SPEED_TRAILER_KMH),
};
const MAX_DAILY_HOURS = Number(cfg.MAX_DAILY_HOURS || 8);
const MAX_TRIPS_PER_VEHICLE_PER_DAY = Number(cfg.MAX_TRIPS_PER_VEHICLE_PER_DAY || 3);
const DAY_START_MIN = Number(cfg.DAY_START_HOUR || 8) * 60;
const DAY_END_MIN = DAY_START_MIN + MAX_DAILY_HOURS * 60;
const EPS = 1e-9;

function cleanText(v) {
  return String(v ?? '')
    .normalize('NFC')
    .replace(/\u0E4D\u0E32/g, '\u0E33')
    .replace(/\u00A0/g, ' ')
    .replace(/[‐‑‒–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}
function norm(v) {
  return cleanText(v).toLowerCase();
}
function normAccount(v) {
  return norm(v)
    .replace(/\s*([,|/()])\s*/g, '$1')
    .replace(/\.+$/g, '')
    .trim();
}
function normPlate(v) {
  return cleanText(v).replace(/\s+/g, '').toUpperCase();
}
function toNumber(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = cleanText(v).replace(/,/g, '');
  if (!s || s === '-' || s === '—') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}
function findKey(obj, needles) {
  const ks = Object.keys(obj || {});
  for (const needle of needles) {
    const n = norm(needle);
    const found = ks.find(k => norm(k).includes(n));
    if (found) return found;
  }
  return null;
}
function getVal(obj, needles) {
  const k = findKey(obj, needles);
  return k ? obj[k] : undefined;
}
function uniq(arr) {
  return [...new Set(arr.filter(v => cleanText(v) !== '').map(v => cleanText(v)))];
}
function pad2(n) { return String(n).padStart(2, '0'); }
function dateKeyUTC(d) {
  return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth()+1)}-${pad2(d.getUTCDate())}`;
}
function addDaysUTC(d, days) {
  const x = new Date(d.getTime());
  x.setUTCDate(x.getUTCDate() + days);
  return x;
}
function parseDateKey(v) {
  if (v instanceof Date && !isNaN(v)) return dateKeyUTC(v);
  if (typeof v === 'number' && Number.isFinite(v)) {
    const ms = Date.UTC(1899, 11, 30) + Math.round(v) * 86400000;
    return dateKeyUTC(new Date(ms));
  }
  const s = cleanText(v);
  if (!s) return null;
  let m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (m) {
    let y = Number(m[3]);
    if (y < 100) y += 2000;
    if (y > 2400) y -= 543;
    const mo = Number(m[2]), da = Number(m[1]);
    const d = new Date(Date.UTC(y, mo - 1, da));
    return isNaN(d) ? null : dateKeyUTC(d);
  }
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) {
    let y = Number(m[1]);
    if (y > 2400) y -= 543;
    const d = new Date(Date.UTC(y, Number(m[2]) - 1, Number(m[3])));
    return isNaN(d) ? null : dateKeyUTC(d);
  }
  const d = new Date(s);
  return isNaN(d) ? null : dateKeyUTC(d);
}
function bkkNowDate() {
  const now = new Date(Date.now() + 7 * 3600 * 1000);
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}
function bkkTimestamp() {
  const now = new Date(Date.now() + 7 * 3600 * 1000);
  return `${dateKeyUTC(now)} ${pad2(now.getUTCHours())}:${pad2(now.getUTCMinutes())}:${pad2(now.getUTCSeconds())}`;
}
function minutesToHHMM(mins) {
  const m = Math.max(0, Math.round(mins));
  const h = Math.floor(m / 60) % 24;
  return `${pad2(h)}:${pad2(m % 60)}`;
}
function round(n, digits = 2) {
  const p = 10 ** digits;
  return Math.round((Number(n) + Number.EPSILON) * p) / p;
}
function vehicleTypeKey(v) {
  const s = norm(v);
  if (!s) return null;
  if (s.includes('พ่วง')) return 'TRAILER';
  if (s.includes('6 ล้อ') || s.includes('6ล้อ')) return 'SIX';
  if (s.includes('กระบะ') || s.includes('4 ล้อ') || s.includes('4ล้อ')) return 'PICKUP';
  return null;
}
function capacityFor(typeKey, volumeMl) {
  if (!Number.isFinite(volumeMl)) return null;
  if (volumeMl >= 100 && volumeMl <= 350) {
    return typeKey === 'PICKUP' ? 8000 : typeKey === 'SIX' ? 35000 : typeKey === 'TRAILER' ? 70000 : null;
  }
  if (volumeMl >= 351 && volumeMl <= 700) {
    return typeKey === 'PICKUP' ? 5500 : typeKey === 'SIX' ? 28000 : typeKey === 'TRAILER' ? 56000 : null;
  }
  if (volumeMl >= 701 && volumeMl <= 1000) {
    return typeKey === 'PICKUP' ? 4000 : typeKey === 'SIX' ? 24000 : typeKey === 'TRAILER' ? 48000 : null;
  }
  return null;
}
function extractVolumeMl(productName, productCode) {
  const name = cleanText(productName);
  const first = name.split('|')[0];
  let m = first.match(/(\d+(?:\.\d+)?)\s*(?:ลิตร|litre|liter|l)\b/i);
  if (m) {
    const x = Number(m[1]);
    if (Number.isFinite(x) && x > 0 && x <= 10) return Math.round(x * 1000);
  }
  m = first.match(/(?:^|\D)(\d{3,4})(?:\D|$)/);
  if (m) {
    const x = Number(m[1]);
    if (x >= 100 && x <= 2000) return x;
  }
  const code = cleanText(productCode);
  const matches = [...code.matchAll(/(?:^|[-_/])(\d{3,4})(?=[-_/]|$)/g)].map(x => Number(x[1]));
  const x = matches.find(x => x >= 100 && x <= 2000);
  return x ?? null;
}
function costOf(cost, typeKey) {
  return typeKey === 'PICKUP' ? cost.pickup : typeKey === 'SIX' ? cost.six : typeKey === 'TRAILER' ? cost.trailer : null;
}
function loadOneTrip(lines, typeKey) {
  let fraction = 0;
  let total = 0;
  const allocations = [];
  for (const line of lines) {
    if (line.remaining <= 0) continue;
    const cap = capacityFor(typeKey, line.volumeMl);
    if (!cap) return { total: 0, allocations: [], fraction: 0 };
    const freeFraction = Math.max(0, 1 - fraction);
    if (freeFraction <= EPS) break;
    let roomQty = Math.floor(freeFraction * cap + EPS);
    if (roomQty <= 0 && freeFraction > EPS) roomQty = 1;
    const take = Math.min(line.remaining, roomQty);
    if (take <= 0) continue;
    allocations.push({ line, qty: take, capacity: cap });
    fraction += take / cap;
    total += take;
    if (fraction >= 1 - EPS) break;
  }
  return { total, allocations, fraction };
}
function remainingQty(lines) {
  return lines.reduce((s, x) => s + Math.max(0, x.remaining), 0);
}
function applyAllocations(allocations) {
  for (const a of allocations) a.line.remaining -= a.qty;
}
function fieldByExactOrContains(row, exacts, contains = []) {
  for (const k of Object.keys(row || {})) {
    const nk = norm(k);
    if (exacts.some(x => nk === norm(x))) return row[k];
  }
  for (const k of Object.keys(row || {})) {
    const nk = norm(k);
    if (contains.some(x => nk.includes(norm(x)))) return row[k];
  }
  return undefined;
}

// ---- Plan week: next Monday through next Saturday in Bangkok ----
// PRODUCTION: use the actual Bangkok date.
// TEST/DEMO: when USE_TEST=true, use TEST_BASE_DATE instead.
// Example TEST_BASE_DATE = 05/08/2026 -> plan 03/08/2026 through 08/08/2026.
const useTest = cfg.USE_TEST === true || norm(cfg.USE_TEST) === 'true';

function dateFromKeyUTC(key) {
  const m = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  return new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
}

let planningBaseDate = bkkNowDate();
let planningBaseDateKey = dateKeyUTC(planningBaseDate);

if (useTest) {
  const testDateRaw = cleanText(cfg.TEST_BASE_DATE);
  if (!testDateRaw) {
    throw new Error('USE_TEST=true แต่ TEST_BASE_DATE ว่าง กรุณากำหนดวันที่ เช่น 05/08/2026');
  }

  const parsedTestDateKey = parseDateKey(testDateRaw);
  if (!parsedTestDateKey) {
    throw new Error(`TEST_BASE_DATE ไม่ถูกต้อง: "${testDateRaw}" กรุณาใช้รูปแบบ DD/MM/YYYY เช่น 05/08/2026`);
  }

  planningBaseDate = dateFromKeyUTC(parsedTestDateKey);
  planningBaseDateKey = parsedTestDateKey;
}

const jsDay = planningBaseDate.getUTCDay(); // 0 Sun ... 6 Sat
const isoDay = jsDay === 0 ? 7 : jsDay;

// Plan the CURRENT week: Monday through Saturday.
const weekStart = addDaysUTC(planningBaseDate, 1 - isoDay);
const weekEnd = addDaysUTC(weekStart, 5);
const weekStartKey = dateKeyUTC(weekStart);
const weekEndKey = dateKeyUTC(weekEnd);
const planWeek = `${weekStartKey}..${weekEndKey}`;
const generatedAt = bkkTimestamp();
const sourceMode = useTest ? 'TEST' : 'PRODUCTION';

// ---- CAR_DATA: all rows map historical plate -> type; only status=open is schedulable ----
const carTypeByPlate = new Map();
const activeVehicles = [];
for (const r of carRows) {
  const id = cleanText(fieldByExactOrContains(r, ['id'], ['id']));
  const rawType = cleanText(fieldByExactOrContains(r, ['type'], ['type']));
  const status = norm(fieldByExactOrContains(r, ['status'], ['status']));
  const driver = cleanText(fieldByExactOrContains(r, ['driver'], ['driver']));
  const typeKey = vehicleTypeKey(rawType);
  if (!id || !typeKey) continue;
  carTypeByPlate.set(normPlate(id), typeKey);
  if (status === 'open') {
    activeVehicles.push({
      id,
      driver,
      typeKey,
      type: CANON[typeKey],
    });
  }
}

// ---- History: owned vehicle types + special historical delivery methods per customer ----
const historyByAccount = new Map();
function ensureHistory(accountKey) {
  if (!historyByAccount.has(accountKey)) {
    historyByAccount.set(accountKey, {
      hasHistory: false,
      ownedTypes: new Set(),
      specialMethods: new Set(),
      unmatchedPlates: new Set(),
    });
  }
  return historyByAccount.get(accountKey);
}
for (const r of history) {
  const account = cleanText(getVal(r, ['Account Name', 'ชื่อบริษัทลูกค้า']));
  if (!account) continue;
  const key = normAccount(account);
  const h = ensureHistory(key);
  h.hasHistory = true;

  const plate = cleanText(getVal(r, ['Truck Plate', 'ทะเบียนรถ']));
  if (!plate) continue;
  const plateNorm = norm(plate);

  if (plateNorm.includes('ลูกค้ารับเอง')) {
    h.specialMethods.add('ลูกค้ารับเอง');
    continue;
  }
  if (plateNorm.includes('รถบรรทุกรับจ้าง')) {
    h.specialMethods.add('รถบรรทุกรับจ้าง');
    continue;
  }

  const typeKey = carTypeByPlate.get(normPlate(plate));
  if (typeKey) h.ownedTypes.add(typeKey);
  else h.unmatchedPlates.add(plate);
}

function resolveHistory(accountKey) {
  const h = historyByAccount.get(accountKey);

  // No history at all = new customer/destination data.
  // Per business rule, all 3 vehicle types are allowed but explicitly marked as NEW.
  if (!h || !h.hasHistory) {
    return {
      hasHistory: false,
      allowed: new Set(['PICKUP', 'SIX', 'TRAILER']),
      specialMethods: new Set(),
      unmatchedPlates: new Set(),
      status: 'NEW_DATA_ALL_TYPES_ALLOWED',
      note: 'ข้อมูลใหม่: ไม่พบประวัติใน FM-DLW-008 จึงอนุญาตรถทั้ง 3 ประเภท',
    };
  }

  if (h.ownedTypes.size > 0) {
    const specialText = [...h.specialMethods].join(', ');
    return {
      hasHistory: true,
      allowed: new Set(h.ownedTypes),
      specialMethods: new Set(h.specialMethods),
      unmatchedPlates: new Set(h.unmatchedPlates),
      status: specialText ? `PASS | ${specialText}` : 'PASS',
      note: specialText ? `พบประวัติพิเศษใน FM-DLW-008: ${specialText}` : '',
    };
  }

  if (h.specialMethods.size > 0) {
    const specialText = [...h.specialMethods].join(', ');
    return {
      hasHistory: true,
      allowed: new Set(),
      specialMethods: new Set(h.specialMethods),
      unmatchedPlates: new Set(h.unmatchedPlates),
      status: specialText,
      note: `FM-DLW-008 ระบุ ${specialText} แต่ไม่มีทะเบียนรถบริษัทที่จับคู่กับ CAR_DATA จึงไม่เดาประเภทรถ`,
    };
  }

  return {
    hasHistory: true,
    allowed: new Set(),
    specialMethods: new Set(),
    unmatchedPlates: new Set(h.unmatchedPlates),
    status: 'HISTORY_PLATE_NOT_IN_CAR_DATA',
    note: `พบประวัติ FM-DLW-008 แต่ทะเบียนรถไม่พบใน CAR_DATA: ${[...h.unmatchedPlates].join(', ')}`,
  };
}

// ---- Cost table: read SD-DLW-006 from clean sub-ranges and join by actual row_number ----
// Source layout from SD-DLW-006:
// B:C = Account + Mileage (header row 2)
// F = Fuel cost (header row 2)
// G:H = Base labor Driver/Helper (header row 3)
// I:J = Pickup trip Driver/Helper (header row 3)
// K:L = 6-wheel trip Driver/Helper (header row 3)
// M:N = Trailer trip Driver/Helper (header row 3)
// O:Q = Toll/extra by Pickup, 6-wheel, Trailer (header row 2)
//
// Final transport cost is calculated only from these Google Sheets node values:
// Pickup  = F + G + H + I + J + O
// 6-wheel = F + G + H + K + L + P
// Trailer = F + G + H + M + N + Q
function rowsBySheetRow(rows) {
  const m = new Map();
  for (const r of rows) {
    const rowNo = toNumber(r.row_number);
    if (!rowNo) continue;
    m.set(rowNo, r);
  }
  return m;
}
function numericValues(r) {
  return Object.entries(r || {})
    .filter(([k]) => k !== 'row_number')
    .map(([, v]) => toNumber(v))
    .filter(v => v !== null);
}
function numByKey(r, needles, fallbackIndex = null) {
  for (const [k, v] of Object.entries(r || {})) {
    if (k === 'row_number') continue;
    const nk = norm(k);
    if (needles.some(n => nk.includes(norm(n)))) {
      return toNumber(v) ?? 0;
    }
  }
  const vals = numericValues(r);
  return fallbackIndex !== null && vals[fallbackIndex] !== undefined ? vals[fallbackIndex] : 0;
}

