const ambiguousPackCodes = new Set();
function formatNumber(n) {
  return Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

function packDetail(productCode, qty) {
  const key = norm(productCode);
  if (!key || ambiguousPackCodes.has(key)) {
    return 'ไม่สามารถคำนวณแพ็คได้ (ข้อมูลแพ็คซ้ำ/ไม่ชัดเจน)';
  }

  const bottlePerPack = bottlePerPackByCode.get(key);
  if (!Number.isFinite(bottlePerPack) || bottlePerPack <= 0) {
    return 'ไม่พบ Product Code ใน Fixed Pack Master';
  }

  const q = Number(qty || 0);
  const fullPacks = Math.floor((q + EPS) / bottlePerPack);
  const remainder = Math.max(0, q - fullPacks * bottlePerPack);
  const packsNeeded = remainder > EPS ? fullPacks + 1 : fullPacks;

  if (remainder <= EPS) {
    return `${formatNumber(packsNeeded)} แพ็ค (${formatNumber(bottlePerPack)} ขวด/แพ็ค)`;
  }

  return `${formatNumber(packsNeeded)} แพ็ค (${formatNumber(fullPacks)} แพ็คเต็ม + ${formatNumber(remainder)} ขวด, ${formatNumber(bottlePerPack)} ขวด/แพ็ค)`;
}

function tripProductLine(line, qty) {
  const productName = cleanText(line.productName).split('|')[0].trim();
  return `${productName} = ${formatNumber(qty)} ขวด = ${packDetail(line.productCode, qty)}`;
}

const costRows = [];
for (const [rowNo, main] of mainByRow.entries()) {
  const account = cleanText(getVal(main, ['Account Name', 'ชื่อบริษัทลูกค้า']));
  if (!account) continue;

  const mileage = toNumber(getVal(main, ['Total Shipping Mileage', 'รวมระยะทางจัดส่งสินค้า']));
  const fuelRow = fuelByRow.get(rowNo) || {};
  const laborRow = laborByRow.get(rowNo) || {};
  const pickupRow = pickupByRow.get(rowNo) || {};
  const sixRow = sixByRow.get(rowNo) || {};
  const trailerRow = trailerByRow.get(rowNo) || {};
  const tollRow = tollByRow.get(rowNo) || {};

  const fuel = numByKey(fuelRow, ['ค่าน้ำมัน'], 0);

  const laborVals = numericValues(laborRow);
  const baseDriver = numByKey(laborRow, ['คนขับ'], 0);
  const baseHelper = numByKey(laborRow, ['เด็กรถ'], 1);

  const pickupVals = numericValues(pickupRow);
  const pickupDriver = numByKey(pickupRow, ['คนขับ'], 0);
  const pickupHelper = numByKey(pickupRow, ['เด็กรถ'], 1);

  const sixVals = numericValues(sixRow);
  const sixDriver = numByKey(sixRow, ['คนขับ'], 0);
  const sixHelper = numByKey(sixRow, ['เด็กรถ'], 1);

  const trailerVals = numericValues(trailerRow);
  const trailerDriver = numByKey(trailerRow, ['คนขับ'], 0);
  const trailerHelper = numByKey(trailerRow, ['เด็กรถ'], 1);

  const tollPickup = numByKey(tollRow, ['กระบะ'], 0);
  const tollSix = numByKey(tollRow, ['6 ล้อ', '6ล้อ'], 1);
  const tollTrailer = numByKey(tollRow, ['พ่วง'], 2);

  costRows.push({
    rowNo,
    account,
    accountKey: normAccount(account),
    mileage,
    pickup: round(fuel + baseDriver + baseHelper + pickupDriver + pickupHelper + tollPickup, 2),
    six: round(fuel + baseDriver + baseHelper + sixDriver + sixHelper + tollSix, 2),
    trailer: round(fuel + baseDriver + baseHelper + trailerDriver + trailerHelper + tollTrailer, 2),
  });
}
const costsByAccount = new Map();
for (const c of costRows) {
  if (!costsByAccount.has(c.accountKey)) costsByAccount.set(c.accountKey, []);
  costsByAccount.get(c.accountKey).push(c);
}
function resolveCost(accountKey) {
  const rows = costsByAccount.get(accountKey) || [];
  if (rows.length === 0) return { status: 'COST_NOT_FOUND', rows: [] };
  const sig = new Map();
  for (const r of rows) {
    const s = JSON.stringify([r.mileage, r.pickup, r.six, r.trailer]);
    if (!sig.has(s)) sig.set(s, r);
  }
  if (sig.size > 1) return { status: 'COST_AMBIGUOUS', rows };
  const only = [...sig.values()][0];
  if (only.mileage === null || !Number.isFinite(only.mileage)) return { status: 'MILEAGE_MISSING', rows };
  return { status: 'OK', rows, cost: only };
}

// ---- Filter FM-DSM-001 and group by shipping date + customer ----
const groups = new Map();
for (const r of orders) {
  const account = cleanText(getVal(r, ['Account Name', 'ชื่อบริษัทลูกค้า']));
  const productName = cleanText(getVal(r, ['Product Name', 'ชื่อสินค้า']));
  const productCode = cleanText(getVal(r, ['Product Code', 'รหัสสินค้า']));
  const amount = toNumber(getVal(r, ['Amount of Product', 'จำนวนสินค้า']));
  const production = toNumber(getVal(r, ['Production Status', 'สถานะการผลิตสินค้า']));
  const shippingStatus = norm(getVal(r, ['Shipping Status', 'สถานะการจัดส่งสินค้า']));
  const shipDate = parseDateKey(getVal(r, ['Schedule Shipping Date', 'วันที่กำหนดจัดส่งสินค้า']));
  const po = cleanText(getVal(r, ['PO No.', 'เลขที่ใบสั่งซื้อ']));
  const so = cleanText(getVal(r, ['SO', 'ใบสั่งขาย']));
  const sourceRow = toNumber(r.row_number) ?? '';

  if (!account || !productName || !amount || amount <= 0 || production === null || !shipDate) continue;
  if (shipDate < weekStartKey || shipDate > weekEndKey) continue;
  if (!(production >= amount)) continue;
  if (shippingStatus !== 'pending') continue;

  const volumeMl = extractVolumeMl(productName, productCode);
  const key = `${shipDate}|${normAccount(account)}`;
  if (!groups.has(key)) {
    groups.set(key, {
      shipDate,
      account,
      accountKey: normAccount(account),
      lines: [],
    });
  }
  groups.get(key).lines.push({
    productName,
    productCode,
    qty: Math.round(amount),
    remaining: Math.round(amount),
    volumeMl,
    po,
    so,
    sourceRow,
  });
}

const destinations = [...groups.values()].map(g => {
  const costResolution = resolveCost(g.accountKey);
  const historyResolution = resolveHistory(g.accountKey);
  const allowed = historyResolution.allowed;
  const unsupported = g.lines.filter(x => capacityFor('PICKUP', x.volumeMl) === null);
  const activeAllowed = activeVehicles.filter(v => allowed.has(v.typeKey));
  const maxDuration = costResolution.status === 'OK' && allowed.size
    ? Math.max(...[...allowed].map(t => SPEED[t] > 0 ? costResolution.cost.mileage / SPEED[t] : 0), 0)
    : 0;
  return {
    ...g,
    costResolution,
    historyResolution,
    allowed,
    activeAllowed,
    unsupported,
    totalQty: g.lines.reduce((s, x) => s + x.qty, 0),
    maxDuration,
  };
});

// Most constrained first; for equal constraints, longer/farther work first, then bigger quantity.
destinations.sort((a, b) => {
  const aa = a.allowed.size || 99;
  const bb = b.allowed.size || 99;
  if (aa !== bb) return aa - bb;
  if (Math.abs(b.maxDuration - a.maxDuration) > EPS) return b.maxDuration - a.maxDuration;
  if (b.totalQty !== a.totalQty) return b.totalQty - a.totalQty;
  return a.account.localeCompare(b.account, 'th');
});

const vehiclesByDay = new Map();
function dayVehicles(dateKey) {
  if (!vehiclesByDay.has(dateKey)) {
    vehiclesByDay.set(dateKey, activeVehicles.map(v => ({
      ...v,
      availableMin: DAY_START_MIN,
      travelHours: 0,
      tripNo: 0,
    })));
  }
  return vehiclesByDay.get(dateKey);
}

const output = [];
function baseOutput(d, status) {
  return {
    'Plan Key': '',
    'Generated At': generatedAt,
    'Source Mode': sourceMode,
    'Plan Week': planWeek,
    'Shipping Date': d.shipDate,
    'Plan Status': status,
    'Account Name': d.account,
    'PO No.': uniq(d.lines.map(x => x.po)).join(', '),
    'SO': uniq(d.lines.map(x => x.so)).join(', '),
    'Product Codes': uniq(d.lines.map(x => x.productCode)).join(', '),
    'Products': uniq(d.lines.map(x => cleanText(x.productName).split('|')[0].trim()).filter(Boolean)).join(', '),
    'Products Detail': d.lines.map(x => `${x.productCode || '-'}: ${x.productName} [${x.qty}]`).join(' | '),
    'Trip Qty': 0,
    'Vehicle ID': '',
    'Driver Name': '',
    'Vehicle Type': '',
    'Vehicle Trip No.': '',
    'Customer Trip No.': '',
    'Departure Time': '',
    'Return Time': '',
    'Travel Hours': '',
    'Vehicle Daily Hours': '',
    'Distance (km)': d.costResolution.cost?.mileage ?? '',
    'Speed (km/h)': '',
    'Estimated Cost': '',
    'Cost Source Row': (d.costResolution.rows || []).map(x => x.rowNo).join(','),
    'Allowed Vehicle Types': [...d.allowed].sort((a,b)=>TYPE_RANK[a]-TYPE_RANK[b]).map(t => CANON[t]).join(', '),
    'History Check': d.historyResolution.status,
    'Load Detail': '',
    'Trip Products Detail': '',
    'Source Rows': d.lines.map(x => x.sourceRow).filter(Boolean).join(','),
    'Remaining Qty After Trip': remainingQty(d.lines),
    'Alert Required': false,
    'Needs Review': false,
    'Remark': '',
  };
}
function pushIssue(d, status, remark, alertRequired = false) {
  const o = baseOutput(d, status);
  o['Plan Key'] = `${planWeek}|${d.shipDate}|${d.accountKey}|ISSUE|${status}`;
  o['Remaining Qty After Trip'] = remainingQty(d.lines);
  o['Alert Required'] = alertRequired;
  o['Needs Review'] = !alertRequired;
  o['Remark'] = remark;
  output.push(o);
}

for (const d of destinations) {
  if (d.unsupported.length) {
    const list = d.unsupported.map(x => `${x.productCode || '-'}=${x.volumeMl ?? 'UNKNOWN'}ml`).join(', ');
    pushIssue(d, 'UNSUPPORTED_VOLUME', `ไม่มี Capacity Rule สำหรับ: ${list}`, false);
    continue;
  }
  if (d.historyResolution.allowed.size === 0) {
    if (d.historyResolution.specialMethods.has('ลูกค้ารับเอง')) {
      const totalQty = remainingQty(d.lines);
      const o = baseOutput(d, 'CUSTOMER_PICKUP');
      o['Plan Key'] = `${planWeek}|${d.shipDate}|${d.accountKey}|SPECIAL|CUSTOMER_PICKUP`;
      o['Trip Qty'] = totalQty;
      o['Trip Products Detail'] = d.lines.map(x => tripProductLine(x, x.qty)).join(' | ');
      o['Remaining Qty After Trip'] = 0;
      o['History Check'] = 'ลูกค้ารับเอง';
      o['Needs Review'] = false;
      o['Alert Required'] = false;
      o['Remark'] = `ลูกค้ารับเอง จำนวนทั้งหมด ${totalQty}`;
      output.push(o);
    } else if (d.historyResolution.specialMethods.size > 0) {
      pushIssue(
        d,
        'HISTORY_SPECIAL_METHOD',
        d.historyResolution.note,
        false
      );
    } else {
      pushIssue(
        d,
        'HISTORY_TYPE_NOT_FOUND',
        d.historyResolution.note,
        false
      );
    }
    continue;
  }

  if (d.costResolution.status !== 'OK') {
    if (d.costResolution.status === 'COST_AMBIGUOUS') {
      pushIssue(d, 'COST_AMBIGUOUS', `พบชื่อลูกค้าซ้ำและมีระยะทาง/ค่าใช้จ่ายต่างกันใน SD-DLW-006 rows ${d.costResolution.rows.map(x=>x.rowNo).join(', ')} จึงไม่เดาค่า`, false);
    } else if (d.costResolution.status === 'MILEAGE_MISSING') {
      pushIssue(d, 'MILEAGE_MISSING', 'พบลูกค้าใน SD-DLW-006 แต่ไม่มี Total Shipping Mileage จึงคำนวณเวลาเดินทางไม่ได้', false);
    } else {
      pushIssue(d, 'COST_NOT_FOUND', 'ไม่พบชื่อลูกค้าใน SD-DLW-006', false);
    }
    continue;
  }
  if (d.activeAllowed.length === 0) {
    pushIssue(d, 'NO_OPEN_ALLOWED_VEHICLE', 'ประเภทที่ลูกค้าเคยรับได้ ไม่มีรถ status=open ใน CAR_DATA', true);
    continue;
  }

  const dayFleet = dayVehicles(d.shipDate);
  let customerTripNo = 0;
  let safety = 0;

  while (remainingQty(d.lines) > 0 && safety++ < 10000) {
    const before = remainingQty(d.lines);
    const candidates = [];

    for (const v of dayFleet) {
      if (!d.allowed.has(v.typeKey)) continue;
      if (v.tripNo >= MAX_TRIPS_PER_VEHICLE_PER_DAY) continue;
      const speed = SPEED[v.typeKey];
      if (!Number.isFinite(speed) || speed <= 0) continue;
      const durationH = d.costResolution.cost.mileage / speed;
      const durationMin = durationH * 60;
      if (durationH > MAX_DAILY_HOURS + EPS) continue;
      if (v.travelHours + durationH > MAX_DAILY_HOURS + EPS) continue;
      if (v.availableMin + durationMin > DAY_END_MIN + EPS) continue;

      const load = loadOneTrip(d.lines, v.typeKey);
      if (load.total <= 0) continue;
      const tripCost = costOf(d.costResolution.cost, v.typeKey);
      if (!Number.isFinite(tripCost)) continue;
      const finishes = load.total >= before;
      const costPerBottle = tripCost / load.total;
      candidates.push({ v, speed, durationH, durationMin, load, tripCost, finishes, costPerBottle });
    }

    if (!candidates.length) break;

    candidates.sort((a, b) => {
      // If one trip finishes the destination, choose the lowest total trip cost.
      if (a.finishes !== b.finishes) return a.finishes ? -1 : 1;
      if (a.finishes && b.finishes && Math.abs(a.tripCost - b.tripCost) > EPS) return a.tripCost - b.tripCost;
      // Otherwise choose lowest cost per delivered bottle.
      if (Math.abs(a.costPerBottle - b.costPerBottle) > EPS) return a.costPerBottle - b.costPerBottle;
      // Prefer earlier available physical vehicle, then smaller type as tie-break.
      if (Math.abs(a.v.availableMin - b.v.availableMin) > EPS) return a.v.availableMin - b.v.availableMin;
      return TYPE_RANK[a.v.typeKey] - TYPE_RANK[b.v.typeKey];
    });

    const c = candidates[0];
    customerTripNo += 1;
    c.v.tripNo += 1;
    const departure = c.v.availableMin;
    const returnMin = departure + c.durationMin;
    applyAllocations(c.load.allocations);
    c.v.availableMin = returnMin;
    c.v.travelHours += c.durationH;

    const o = baseOutput(d, 'SCHEDULED');
    o['Plan Key'] = `${planWeek}|${d.shipDate}|${d.accountKey}|TRIP|${customerTripNo}`;
    o['Trip Qty'] = c.load.total;
    o['Vehicle ID'] = c.v.id;
    o['Driver Name'] = c.v.driver || '';
    o['Vehicle Type'] = c.v.type;
    o['Vehicle Trip No.'] = c.v.tripNo;
    o['Customer Trip No.'] = customerTripNo;
    o['Departure Time'] = minutesToHHMM(departure);
    o['Return Time'] = minutesToHHMM(returnMin);
    o['Travel Hours'] = round(c.durationH, 2);
    o['Vehicle Daily Hours'] = round(c.v.travelHours, 2);
    o['Distance (km)'] = d.costResolution.cost.mileage;
    o['Speed (km/h)'] = c.speed;
    o['Estimated Cost'] = c.tripCost;
    o['Cost Source Row'] = d.costResolution.cost.rowNo;
    o['History Check'] = d.historyResolution.status;
    o['Load Detail'] = c.load.allocations.map(a => `${a.line.productCode || '-'}:${a.qty} (${a.line.volumeMl}ml)`).join(' | ');
    o['Trip Products Detail'] = c.load.allocations.map(a => tripProductLine(a.line, a.qty)).join(' | ');
    o['Source Rows'] = uniq(c.load.allocations.map(a => a.line.sourceRow)).join(',');
    o['Remaining Qty After Trip'] = remainingQty(d.lines);
    o['Remark'] = [`ใช้ระยะทางรวม ${d.costResolution.cost.mileage} km / ${c.speed} km/h`, d.historyResolution.note].filter(Boolean).join(' | ');
    output.push(o);
  }

  if (remainingQty(d.lines) > 0) {
    const anyAllowedSpeed = [...d.allowed].some(t => Number.isFinite(SPEED[t]) && SPEED[t] > 0);
    const allTripsTooLong = [...d.allowed].every(t => !Number.isFinite(SPEED[t]) || SPEED[t] <= 0 || d.costResolution.cost.mileage / SPEED[t] > MAX_DAILY_HOURS + EPS);
    if (!anyAllowedSpeed) {
      pushIssue(d, 'SPEED_CONFIG_MISSING', 'ไม่มีค่าความเร็วที่ใช้งานได้สำหรับประเภทรถที่ลูกค้าอนุญาต', false);
    } else if (allTripsTooLong) {
      pushIssue(d, 'TRIP_TIME_EXCEEDS_DAY', `ระยะทาง/ความเร็วทำให้เที่ยวเดียวใช้เวลาเกิน ${MAX_DAILY_HOURS} ชั่วโมง`, true);
    } else {
      pushIssue(d, 'DAILY_CAPACITY_EXCEEDED', `หลังจัดรถตั้งแต่ ${minutesToHHMM(DAY_START_MIN)} จำกัดรถละ ${MAX_DAILY_HOURS} ชั่วโมง และไม่เกิน ${MAX_TRIPS_PER_VEHICLE_PER_DAY} รอบ/คัน/วัน ยังเหลือ ${remainingQty(d.lines)} ขวด`, true);
    }
  }
}

// Sort output for an operational dispatch view.
output.sort((a, b) => {
  if (a['Shipping Date'] !== b['Shipping Date']) return String(a['Shipping Date']).localeCompare(String(b['Shipping Date']));
  const at = a['Departure Time'] || '99:99';
  const bt = b['Departure Time'] || '99:99';
  if (at !== bt) return at.localeCompare(bt);
  if (a['Vehicle ID'] !== b['Vehicle ID']) return String(a['Vehicle ID']).localeCompare(String(b['Vehicle ID']), 'th');
  return String(a['Account Name']).localeCompare(String(b['Account Name']), 'th');
});


// ---- Fixed demo/operational slots for vehicles with exactly 2 trips in the same day ----
// Business rule: if one physical vehicle has exactly two SCHEDULED trips on a day,
// display trip 1 as 08:00-12:00 and trip 2 as 13:00-17:00.
// Travel Hours remains the calculated travel time from mileage/speed; only the planned clock slots are fixed.
const tripsByVehicleDay = new Map();
for (const row of output) {
  if (row['Plan Status'] !== 'SCHEDULED') continue;
  const vehicleId = cleanText(row['Vehicle ID']);
  const shipDate = cleanText(row['Shipping Date']);
  if (!vehicleId || !shipDate) continue;
  const key = `${shipDate}|${vehicleId}`;
  if (!tripsByVehicleDay.has(key)) tripsByVehicleDay.set(key, []);
  tripsByVehicleDay.get(key).push(row);
}

for (const trips of tripsByVehicleDay.values()) {
  if (trips.length !== 2) continue;
  trips.sort((a, b) => Number(a['Vehicle Trip No.'] || 0) - Number(b['Vehicle Trip No.'] || 0));

  trips[0]['Departure Time'] = '08:00';
  trips[0]['Return Time'] = '12:00';

  trips[1]['Departure Time'] = '13:00';
  trips[1]['Return Time'] = '17:00';

  for (const trip of trips) {
    const fixedNote = 'รถคันนี้มี 2 เที่ยว/วัน: กำหนดเวลา 08:00-12:00 และ 13:00-17:00';
    trip['Remark'] = trip['Remark'] ? `${trip['Remark']} | ${fixedNote}` : fixedNote;
  }
}

return output.map(json => ({ json }));
